// Amount in yen before rounding: the customer's discount rate (0.1 = 10%) is applied
// once, then carts with 10 or more lines get an extra 5% bulk discount, also once.
export function amount(items, discount = 0) {
  const subtotal = items.reduce((sum, item) => sum + item.price * item.qty, 0);
  const bulk = items.length >= 10 ? 0.05 : 0;
  return subtotal * (1 - discount) * (1 - bulk);
}

// Cart total in yen. Fractions of a yen are dropped.
export function total(items, discount = 0) {
  // Clear binary floating-point noise first, so that an amount that is exactly
  // 2021 yen but comes out as 2020.9999999999998 is not cut down to 2020.
  return Math.floor(Number(amount(items, discount).toPrecision(12)));
}

export function itemCount(items) {
  return items.reduce((n, item) => n + item.qty, 0);
}

